source.exploreUrl:
@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});


fl=[
["男频",[["东方玄幻","25",],["军事战争","14",],["现代都市","73",],["二次元","81",],["西方奇幻","61",],["历史架空","60",],["灵异悬疑","58",],["游戏竞技","56",],["科幻末世","53",],["武侠仙侠","28",],["官场职场","27",],["同人小说","26",]]],
["女频",[["穿越重生","70",],["豪门总裁","69",],["现代言情","68",],["武侠仙侠","67",],["古言架空","33",],["婚恋情感","32",],["青春校园","31",],["幻想异能","21",],["同人美文","30",]]],
["出版",[["现代都市","51",],["青春校园","50",],["悬疑灵异","49",],["励志成功","48",],["官场沉浮","47",],["职场商战","46",],["铁血军事","45",],["历史风云","44",],["影视娱乐","38",],["经管理财","37",],["教育教辅","36",],["纪实传记","35",],["奇幻科幻","24",],["生活休闲","23",],["武侠仙侠","22",],["童话寓言","74",],["社科科普","75",],["外国名著","76",],["古典名著","77"],["当代文学","78",],["两性伦理","79"],["言情小说","80"]]]
];
fl.map([title,list]=>{		
	push(title,null,1, 1);
list.map(([title,id],index)=>{ 
	url=`/api/book/cate/list/m/?page={{page}}&cate_id=${id}&sort=1`;     
					if(index+1 <= list.length - list.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.3);}
				});
	});
JSON.stringify(sort);

source.header:
{
	"User-Agent": "Mozilla/5.0 (Linux; Android 9) Mobile Safari/537.36",
"Referer": "{{baseUrl}}"
	}

ruleBookInfo.tocUrl:
.active@href
@js:
var url=source.key+result;
var web=java.webView(null,url,null),
j=org.jsoup.Jsoup.parse(web);
var page=j.select(".f-cb li").length;
java.put("page",page);
result.replace('/m/',"/api/");

ruleToc.nextTocUrl:
@js:
var page=java.get("page");
var url=[];
if(page){
	for(i=2;i<=page;i++){
		var next=baseUrl.replace(/\d+.$/,i+"/")
		url.push(next);
		}
	}
url;

